import java.util.ArrayList;
import java.util.List;

public class LedgerCloserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object call(int balance, int delta, List<String> log) {
        try {
            return LedgerCloser.applyAndClose(balance, delta, log);
        } catch (Throwable crash) {
            return "threw " + crash.getClass().getSimpleName();
        }
    }

    static Object thrown(int balance, int delta, List<String> log) {
        try {
            LedgerCloser.applyAndClose(balance, delta, log);
            return "<no exception>";
        } catch (IllegalArgumentException rejected) {
            return rejected.getClass().getSimpleName() + ": " + rejected.getMessage();
        } catch (Throwable crash) {
            return "threw " + crash.getClass().getSimpleName();
        }
    }

    static Object all(int balance, int[] deltas, List<String> log) {
        try {
            return LedgerCloser.applyAll(balance, deltas, log);
        } catch (Throwable crash) {
            return "threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        List<String> log = new ArrayList<>();
        check("a legal withdrawal returns the new balance", 70, call(100, -30, log));
        check("the log after a legal withdrawal", "[apply -30, close]", log.toString());

        List<String> zeroLog = new ArrayList<>();
        check("spending down to exactly zero is allowed", 0, call(5, -5, zeroLog));
        List<String> failLog = new ArrayList<>();
        check("an overdraft escapes the method", "IllegalArgumentException: overdraft",
                thrown(10, -50, failLog));
        check("the finally block still ran", "[apply -50, close]", failLog.toString());

        List<String> batchLog = new ArrayList<>();
        check("applyAll skips the rejected delta", 120,
                all(100, new int[] {-30, -200, 50}, batchLog));
        check("the log of the whole batch",
                "[apply -30, close, apply -200, close, rejected -200, apply 50, close]",
                batchLog.toString());

        List<String> emptyLog = new ArrayList<>();
        check("applyAll with no deltas leaves the balance alone", 100,
                all(100, new int[] {}, emptyLog));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

