/**
 * TASK: Use finally for cleanup WITHOUT letting it swallow the result.
 *
 * applyAndClose(balance, delta, log):
 *   1. adds "apply " + delta to the log,
 *   2. throws IllegalArgumentException("overdraft") when balance + delta would
 *      be negative -- that exception must reach the caller,
 *   3. otherwise returns the new balance,
 *   4. and in EVERY case adds "close" to the log as the final entry, from a
 *      finally block.
 *
 * The trap: a return statement inside finally replaces the real result AND
 * quietly discards an exception that was on its way out. The finally block here
 * should only log.
 *
 * applyAll(balance, deltas, log) applies each delta in turn with
 * applyAndClose. A delta that is rejected leaves the balance untouched and adds
 * "rejected " + delta to the log, then the loop carries on. The final balance
 * is returned.
 *
 * Example: applyAndClose(100, -30, log) -> 70, log [apply -30, close]
 *          applyAll(100, {-30, -200, 50}, log) -> 120, log
 *          [apply -30, close, apply -200, close, rejected -200, apply 50, close]
 */
import java.util.List;

public class LedgerCloser {

    public static int applyAndClose(int balance, int delta, List<String> log) {
        try {
            log.add("apply " + delta);
            int updated = balance + delta;
            if (updated < 0) {
                throw new IllegalArgumentException("overdraft");
            }
            return updated;
        } finally {
            log.add("close");
        }
    }

    public static int applyAll(int balance, int[] deltas, List<String> log) {
        int current = balance;
        for (int delta : deltas) {
            try {
                current = applyAndClose(current, delta, log);
            } catch (IllegalArgumentException rejected) {
                log.add("rejected " + delta);
            }
        }
        return current;
    }
}
